"use client";

/**
 * Website analytics: the top of the v2 Website landing screen (northwind).
 *
 * DEMO DATA. Every number here is generated by `buildMock` below from a fixed
 * seed. Nothing is queried and nothing is tracked yet. It exists to show what
 * the screen will look like once the v2 site reports page views. When real
 * analytics land, replace `buildMock` with a hook that returns the same
 * `Analytics` shape and leave the layout alone.
 *
 * Styling follows the v2 dashboard: `.pv` tokens (HOME_PALETTE), flat 1px
 * cards with no shadow, a single accent for magnitude, and status colours only
 * for real states (the speed checks).
 */

import { useEffect, useMemo, useState, type ReactNode } from "react";
import { format, subDays } from "date-fns";
import {
  Area,
  AreaChart,
  Bar,
  BarChart,
  CartesianGrid,
  Line,
  ResponsiveContainer,
  Tooltip,
  XAxis,
  YAxis,
} from "recharts";
import { Check } from "lucide-react";

import { cn } from "@/lib/utils";
import { Eyebrow, MagnitudeBar, Spark } from "@/components/dashboard-v2/home/ui";

type Range = "7d" | "30d" | "90d";
const RANGES: { key: Range; label: string; days: number }[] = [
  { key: "7d", label: "7 days", days: 7 },
  { key: "30d", label: "30 days", days: 30 },
  { key: "90d", label: "90 days", days: 90 },
];

interface DayPoint {
  date: string;
  visitors: number;
  previous: number;
  bookings: number;
  signedIn: number;
}

interface Analytics {
  days: DayPoint[];
  totals: { visitors: number; bookings: number; signedIn: number; conversion: number };
  previous: { visitors: number; bookings: number; signedIn: number; conversion: number };
  funnel: { label: string; value: number }[];
  sources: { label: string; value: number }[];
  pages: { path: string; name: string; views: number; avgTime: string }[];
  devices: { label: string; share: number }[];
}

/* ─── mock ──────────────────────────────────────────────────────────────── */

function rng(seed: number) {
  return () => {
    seed |= 0;
    seed = (seed + 0x6d2b79f5) | 0;
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function buildMock(days: number): Analytics {
  const r = rng(days * 7919 + 247);
  const today = new Date();
  const points: DayPoint[] = Array.from({ length: days }, (_, i) => {
    const date = subDays(today, days - 1 - i);
    const dow = date.getDay();
    const weekend = dow === 5 || dow === 6 ? 1.28 : dow === 0 ? 1.12 : 1;
    const trend = 1 + (i / Math.max(1, days - 1)) * 0.22;
    const visitors = Math.round(210 * weekend * trend * (0.86 + r() * 0.28));
    const previous = Math.round(210 * weekend * 0.84 * (0.86 + r() * 0.28));
    const bookings = Math.max(0, Math.round(visitors * (0.022 + r() * 0.014)));
    const signedIn = Math.round(visitors * (0.09 + r() * 0.04));
    return { date: format(date, "yyyy-MM-dd"), visitors, previous, bookings, signedIn };
  });

  const sum = (k: keyof DayPoint) => points.reduce((a, p) => a + (p[k] as number), 0);
  const visitors = sum("visitors");
  const bookings = sum("bookings");
  const signedIn = sum("signedIn");
  const prevVisitors = sum("previous");
  const prevBookings = Math.round(bookings * 0.72);

  return {
    days: points,
    totals: { visitors, bookings, signedIn, conversion: (bookings / visitors) * 100 },
    previous: {
      visitors: prevVisitors,
      bookings: prevBookings,
      signedIn: Math.round(signedIn * 0.86),
      conversion: (prevBookings / prevVisitors) * 100,
    },
    funnel: [
      { label: "Visited the site", value: visitors },
      { label: "Looked at a car", value: Math.round(visitors * 0.58) },
      { label: "Started a booking", value: Math.round(visitors * 0.11) },
      { label: "Booked and paid", value: bookings },
    ],
    sources: [
      { label: "Google search", value: Math.round(visitors * 0.44) },
      { label: "Direct", value: Math.round(visitors * 0.23) },
      { label: "Instagram", value: Math.round(visitors * 0.14) },
      { label: "Facebook", value: Math.round(visitors * 0.09) },
      { label: "Google Maps", value: Math.round(visitors * 0.06) },
      { label: "Other", value: Math.round(visitors * 0.04) },
    ],
    pages: [
      { path: "/", name: "Home", views: Math.round(visitors * 0.92), avgTime: "0:48" },
      { path: "/fleet", name: "Fleet", views: Math.round(visitors * 0.61), avgTime: "1:52" },
      { path: "/booking", name: "Booking", views: Math.round(visitors * 0.17), avgTime: "3:10" },
      { path: "/reviews", name: "Reviews", views: Math.round(visitors * 0.12), avgTime: "1:05" },
      { path: "/about", name: "About", views: Math.round(visitors * 0.08), avgTime: "0:41" },
      { path: "/contact", name: "Contact", views: Math.round(visitors * 0.05), avgTime: "0:36" },
    ],
    devices: [
      { label: "Phone", share: 68 },
      { label: "Desktop", share: 28 },
      { label: "Tablet", share: 4 },
    ],
  };
}

/* ─── helpers ───────────────────────────────────────────────────────────── */

const num = (n: number) => n.toLocaleString("en-US");
const pctChange = (now: number, before: number) =>
  before > 0 ? Math.round(((now - before) / before) * 100) : 0;

function Change({ value, suffix = "%" }: { value: number; suffix?: string }) {
  const up = value >= 0;
  return (
    <span
      className={cn(
        "text-[11.5px] font-semibold tabular-nums",
        up ? "text-[var(--pv-clear)]" : "text-[var(--pv-late)]",
      )}
    >
      {up ? "↑" : "↓"} {Math.abs(value)}
      {suffix}
    </span>
  );
}

/** A flat panel: 1px line, no shadow, the v2 motion on entry. */
function Panel({
  title,
  aside,
  delay = 0,
  className,
  children,
}: {
  title: string;
  aside?: ReactNode;
  delay?: number;
  className?: string;
  children: ReactNode;
}) {
  return (
    <section
      className={cn(
        "flex min-w-0 flex-col rounded-2xl border border-[var(--pv-line)] bg-[var(--pv-paper)] p-5",
        "animate-in fade-in-0 slide-in-from-bottom-3 fill-mode-both duration-200 ease-out",
        className,
      )}
      style={{ animationDelay: `${delay}ms` }}
    >
      <header className="mb-4 flex items-center justify-between gap-3">
        <Eyebrow>{title}</Eyebrow>
        {aside}
      </header>
      {children}
    </section>
  );
}

function TipShell({ label, children }: { label: string; children: ReactNode }) {
  return (
    <div className="min-w-[170px] rounded-xl border border-[var(--pv-line)] bg-[var(--pv-paper)] px-3.5 py-3 text-[12px]">
      <p className="text-[11px] font-medium text-[var(--pv-ink-3)]">{label}</p>
      {children}
    </div>
  );
}

function TipRow({ label, value, swatch }: { label: string; value: string; swatch?: ReactNode }) {
  return (
    <p className="mt-1 flex items-center justify-between gap-4 text-[var(--pv-ink-2)]">
      <span className="flex items-center gap-1.5">
        {swatch}
        {label}
      </span>
      <span className="font-semibold tabular-nums text-[var(--pv-ink)]">{value}</span>
    </p>
  );
}

/** Visitors on the site right now. Demo: drifts a little every few seconds. */
function LiveNow() {
  const [n, setN] = useState(14);
  useEffect(() => {
    const t = setInterval(() => {
      setN((v) => Math.min(21, Math.max(8, v + Math.round(Math.random() * 4 - 2))));
    }, 3500);
    return () => clearInterval(t);
  }, []);
  return (
    <span className="inline-flex items-center gap-2 rounded-full border border-[var(--pv-line)] bg-[var(--pv-paper)] px-3 py-1 text-[12px] text-[var(--pv-ink-2)]">
      <span className="relative flex size-2">
        <span className="absolute inline-flex size-full animate-ping rounded-full bg-[var(--pv-clear)] opacity-60" />
        <span className="relative inline-flex size-2 rounded-full bg-[var(--pv-clear)]" />
      </span>
      <span className="font-semibold tabular-nums text-[var(--pv-ink)]">{n}</span> on your site now
    </span>
  );
}

function RangeSwitch({ value, onChange }: { value: Range; onChange: (r: Range) => void }) {
  return (
    <div className="inline-flex rounded-full border border-[var(--pv-line)] bg-[var(--pv-paper)] p-0.5">
      {RANGES.map((r) => (
        <button
          key={r.key}
          type="button"
          onClick={() => onChange(r.key)}
          className={cn(
            "rounded-full px-3 py-1 text-[12px] font-medium transition-colors duration-200",
            value === r.key
              ? "bg-[var(--pv-accent-bg)] text-[var(--pv-accent-ink)]"
              : "text-[var(--pv-ink-3)] hover:text-[var(--pv-ink)]",
          )}
        >
          {r.label}
        </button>
      ))}
    </div>
  );
}

/* ─── main ──────────────────────────────────────────────────────────────── */

export function WebsiteAnalytics() {
  const [range, setRange] = useState<Range>("30d");
  const days = RANGES.find((r) => r.key === range)!.days;
  const data = useMemo(() => buildMock(days), [days]);
  const { totals, previous } = data;

  // 90 days of daily bars is a comb; group them into weeks.
  const bookingBars = useMemo(() => {
    if (days <= 30) return data.days.map((d) => ({ date: d.date, bookings: d.bookings, label: format(new Date(d.date), "EEE d MMM") }));
    const weeks: { date: string; bookings: number; label: string }[] = [];
    for (let i = 0; i < data.days.length; i += 7) {
      const chunk = data.days.slice(i, i + 7);
      weeks.push({
        date: chunk[0].date,
        bookings: chunk.reduce((a, d) => a + d.bookings, 0),
        label: `Week of ${format(new Date(chunk[0].date), "d MMM")}`,
      });
    }
    return weeks;
  }, [data, days]);

  const kpis = [
    {
      label: "Visitors",
      value: num(totals.visitors),
      change: pctChange(totals.visitors, previous.visitors),
      spark: data.days.map((d) => d.visitors),
    },
    {
      label: "Bookings from the site",
      value: num(totals.bookings),
      change: pctChange(totals.bookings, previous.bookings),
      spark: data.days.map((d) => d.bookings),
    },
    {
      label: "Visitors who book",
      value: `${totals.conversion.toFixed(1)}%`,
      change: Math.round((totals.conversion - previous.conversion) * 10) / 10,
      suffix: "pt",
      spark: data.days.map((d) => (d.bookings / d.visitors) * 100),
    },
    {
      label: "Signed-in customers",
      value: num(totals.signedIn),
      change: pctChange(totals.signedIn, previous.signedIn),
      spark: data.days.map((d) => d.signedIn),
    },
  ];

  const funnelMax = data.funnel[0].value;
  const sourceMax = data.sources[0].value;
  const pageMax = data.pages[0].views;
  const tickEvery = days <= 7 ? 0 : days <= 30 ? 6 : 14;

  return (
    <div className="space-y-4">
      <div className="flex flex-wrap items-center justify-between gap-3">
        <LiveNow />
        <RangeSwitch value={range} onChange={setRange} />
      </div>

      {/* Headline numbers */}
      <div className="grid grid-cols-2 gap-4 lg:grid-cols-4">
        {kpis.map((k, i) => (
          <section
            key={k.label}
            className="animate-in fade-in-0 slide-in-from-bottom-3 fill-mode-both rounded-2xl border border-[var(--pv-line)] bg-[var(--pv-paper)] p-5 duration-200 ease-out"
            style={{ animationDelay: `${i * 40}ms` }}
          >
            <p className="text-[12px] text-[var(--pv-ink-3)]">{k.label}</p>
            <div className="mt-2 flex items-baseline gap-2">
              <span className="text-[26px] font-semibold leading-none tracking-[-0.03em] tabular-nums text-[var(--pv-ink)]">
                {k.value}
              </span>
              <Change value={k.change} suffix={k.suffix} />
            </div>
            <div className="mt-4">
              <Spark data={k.spark} color="var(--pv-accent)" height={30} />
            </div>
          </section>
        ))}
      </div>

      {/* Visitors over time + funnel */}
      <div className="grid gap-4 lg:grid-cols-3">
        <Panel
          title="Visitors"
          delay={160}
          className="lg:col-span-2"
          aside={
            <span className="flex items-center gap-4 text-[11.5px] text-[var(--pv-ink-3)]">
              <span className="flex items-center gap-1.5">
                <span className="h-0.5 w-3.5 rounded-full bg-[var(--pv-accent)]" />
                This period
              </span>
              <span className="flex items-center gap-1.5">
                <span className="w-3.5 border-t-2 border-dashed border-[var(--pv-line-2)]" />
                Period before
              </span>
            </span>
          }
        >
          <div className="h-[230px] text-[var(--pv-accent)]">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={data.days} margin={{ top: 6, right: 6, bottom: 0, left: -18 }}>
                <defs>
                  <linearGradient id="wa-visitors" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="0%" style={{ stopColor: "currentColor", stopOpacity: 0.22 }} />
                    <stop offset="100%" style={{ stopColor: "currentColor", stopOpacity: 0 }} />
                  </linearGradient>
                </defs>
                <CartesianGrid vertical={false} stroke="var(--pv-line)" />
                <XAxis
                  dataKey="date"
                  tickLine={false}
                  axisLine={false}
                  interval={tickEvery}
                  tick={{ fontSize: 11, fill: "var(--pv-ink-3)" }}
                  tickFormatter={(d) => format(new Date(d), days <= 7 ? "EEE" : "d MMM")}
                  dy={6}
                />
                <YAxis
                  tickLine={false}
                  axisLine={false}
                  width={48}
                  tick={{ fontSize: 11, fill: "var(--pv-ink-3)" }}
                />
                <Tooltip
                  cursor={{ stroke: "var(--pv-line-2)", strokeWidth: 1 }}
                  content={({ active, payload }) => {
                    if (!active || !payload?.length) return null;
                    const p = payload[0].payload as DayPoint;
                    return (
                      <TipShell label={format(new Date(p.date), "EEEE d MMM")}>
                        <p className="mt-1 text-[17px] font-semibold tabular-nums tracking-[-0.02em] text-[var(--pv-ink)]">
                          {num(p.visitors)}
                        </p>
                        <p className="text-[11.5px] text-[var(--pv-ink-3)]">visitors</p>
                        <div className="mt-2 border-t border-[var(--pv-line)] pt-1.5">
                          <TipRow label="Period before" value={num(p.previous)} />
                          <TipRow label="Bookings" value={num(p.bookings)} />
                        </div>
                      </TipShell>
                    );
                  }}
                />
                <Line
                  type="monotone"
                  dataKey="previous"
                  stroke="var(--pv-line-2)"
                  strokeWidth={2}
                  strokeDasharray="4 4"
                  dot={false}
                  activeDot={false}
                  isAnimationActive={false}
                />
                <Area
                  type="monotone"
                  dataKey="visitors"
                  stroke="currentColor"
                  strokeWidth={2}
                  fill="url(#wa-visitors)"
                  activeDot={{ r: 4.5, stroke: "var(--pv-paper)", strokeWidth: 2, fill: "currentColor" }}
                  animationDuration={500}
                />
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </Panel>

        <Panel title="From visit to booking" delay={200}>
          <ol className="flex flex-1 flex-col justify-between gap-4">
            {data.funnel.map((s, i) => {
              const prev = i > 0 ? data.funnel[i - 1].value : null;
              return (
                <li key={s.label}>
                  <div className="flex items-baseline justify-between gap-3 text-[12.5px]">
                    <span className="text-[var(--pv-ink-2)]">{s.label}</span>
                    <span className="font-semibold tabular-nums text-[var(--pv-ink)]">{num(s.value)}</span>
                  </div>
                  <div className="mt-1.5 h-2 overflow-hidden rounded-full bg-[var(--pv-wash)]">
                    <div
                      className="h-full rounded-full bg-[var(--pv-accent)] transition-[width] duration-500 ease-out"
                      style={{ width: `${Math.max(2, (s.value / funnelMax) * 100)}%`, opacity: 1 - i * 0.18 }}
                    />
                  </div>
                  {prev !== null && (
                    <p className="mt-1 text-[11px] tabular-nums text-[var(--pv-ink-3)]">
                      {((s.value / prev) * 100).toFixed(0)}% of the step before
                    </p>
                  )}
                </li>
              );
            })}
          </ol>
        </Panel>
      </div>

      {/* Bookings, speed, sources */}
      <div className="grid gap-4 lg:grid-cols-3">
        <Panel
          title="Bookings from the site"
          delay={240}
          aside={<span className="text-[11.5px] tabular-nums text-[var(--pv-ink-3)]">{num(totals.bookings)} total</span>}
        >
          <div className="min-h-[190px] flex-1 text-[var(--pv-accent)]">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={bookingBars} margin={{ top: 6, right: 0, bottom: 0, left: -12 }} barCategoryGap={days <= 7 ? "28%" : "18%"}>
                <CartesianGrid vertical={false} stroke="var(--pv-line)" />
                <XAxis dataKey="date" hide />
                <YAxis
                  tickLine={false}
                  axisLine={false}
                  allowDecimals={false}
                  width={40}
                  tick={{ fontSize: 11, fill: "var(--pv-ink-3)" }}
                />
                <Tooltip
                  cursor={{ fill: "var(--pv-wash)" }}
                  content={({ active, payload }) => {
                    if (!active || !payload?.length) return null;
                    const p = payload[0].payload as { label: string; bookings: number };
                    return (
                      <TipShell label={p.label}>
                        <p className="mt-1 text-[17px] font-semibold tabular-nums text-[var(--pv-ink)]">{p.bookings}</p>
                        <p className="text-[11.5px] text-[var(--pv-ink-3)]">{p.bookings === 1 ? "booking" : "bookings"}</p>
                      </TipShell>
                    );
                  }}
                />
                <Bar dataKey="bookings" fill="currentColor" radius={[4, 4, 0, 0]} animationDuration={500} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </Panel>

        <Panel
          title="Site speed"
          delay={280}
          aside={
            <span className="inline-flex items-center gap-1 text-[11.5px] font-medium text-[var(--pv-clear)]">
              <Check className="size-3.5" strokeWidth={2.5} /> Fast
            </span>
          }
        >
          <div className="flex items-center gap-5">
            <SpeedRing score={96} />
            <div className="min-w-0">
              <p className="text-[13px] font-medium text-[var(--pv-ink)]">Faster than most sites</p>
              <p className="mt-0.5 text-[12px] leading-relaxed text-[var(--pv-ink-3)]">
                Pages open in 1.2s on average, on phones as well as desktops.
              </p>
            </div>
          </div>
          <dl className="mt-5 space-y-2.5 border-t border-[var(--pv-line)] pt-4 text-[12.5px]">
            {[
              { k: "Main content shows", v: "1.4s" },
              { k: "Responds to a tap", v: "96ms" },
              { k: "Layout stays still", v: "0.02" },
              { k: "Up time", v: "99.98%" },
            ].map((m) => (
              <div key={m.k} className="flex items-center justify-between gap-3">
                <dt className="text-[var(--pv-ink-2)]">{m.k}</dt>
                <dd className="flex items-center gap-2 tabular-nums">
                  <span className="font-semibold text-[var(--pv-ink)]">{m.v}</span>
                  <span className="inline-flex items-center gap-0.5 text-[11px] font-medium text-[var(--pv-clear)]">
                    <Check className="size-3" strokeWidth={2.75} /> Good
                  </span>
                </dd>
              </div>
            ))}
          </dl>
        </Panel>

        <Panel title="Where visitors come from" delay={320}>
          <ul className="space-y-3">
            {data.sources.map((s) => (
              <li key={s.label}>
                <div className="mb-1.5 flex items-baseline justify-between gap-3 text-[12.5px]">
                  <span className="text-[var(--pv-ink-2)]">{s.label}</span>
                  <span className="tabular-nums text-[var(--pv-ink)]">
                    <span className="font-semibold">{num(s.value)}</span>
                    <span className="ml-1.5 text-[11px] text-[var(--pv-ink-3)]">
                      {Math.round((s.value / totals.visitors) * 100)}%
                    </span>
                  </span>
                </div>
                <MagnitudeBar value={s.value} max={sourceMax} />
              </li>
            ))}
          </ul>
        </Panel>
      </div>

      {/* Pages + devices */}
      <div className="grid gap-4 lg:grid-cols-3">
        <Panel title="Most viewed pages" delay={360} className="lg:col-span-2">
          <table className="w-full text-[12.5px]">
            <thead>
              <tr className="text-left text-[11px] text-[var(--pv-ink-3)]">
                <th className="pb-2 font-medium">Page</th>
                <th className="w-[40%] pb-2 font-medium" />
                <th className="pb-2 text-right font-medium">Views</th>
                <th className="pb-2 pl-4 text-right font-medium">Time on page</th>
              </tr>
            </thead>
            <tbody>
              {data.pages.map((p) => (
                <tr key={p.path} className="border-t border-[var(--pv-line)]">
                  <td className="py-2.5">
                    <span className="font-medium text-[var(--pv-ink)]">{p.name}</span>
                    <span className="ml-2 text-[11px] text-[var(--pv-ink-3)]">{p.path}</span>
                  </td>
                  <td className="py-2.5 pr-2">
                    <MagnitudeBar value={p.views} max={pageMax} />
                  </td>
                  <td className="py-2.5 text-right font-semibold tabular-nums text-[var(--pv-ink)]">{num(p.views)}</td>
                  <td className="py-2.5 pl-4 text-right tabular-nums text-[var(--pv-ink-2)]">{p.avgTime}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </Panel>

        <Panel title="Devices" delay={400}>
          <div className="flex h-3 w-full gap-0.5 overflow-hidden rounded-full">
            {data.devices.map((d, i) => (
              <span
                key={d.label}
                className="h-full bg-[var(--pv-accent)] first:rounded-l-full last:rounded-r-full"
                style={{ width: `${d.share}%`, opacity: 1 - i * 0.32 }}
              />
            ))}
          </div>
          <ul className="mt-5 space-y-3 text-[12.5px]">
            {data.devices.map((d, i) => (
              <li key={d.label} className="flex items-center justify-between gap-3">
                <span className="flex items-center gap-2 text-[var(--pv-ink-2)]">
                  <span className="size-2 rounded-full bg-[var(--pv-accent)]" style={{ opacity: 1 - i * 0.32 }} />
                  {d.label}
                </span>
                <span className="font-semibold tabular-nums text-[var(--pv-ink)]">{d.share}%</span>
              </li>
            ))}
          </ul>
          <p className="mt-auto pt-5 text-[12px] leading-relaxed text-[var(--pv-ink-3)]">
            Most of your customers book from a phone, so the mobile site is the one that earns.
          </p>
        </Panel>
      </div>
    </div>
  );
}

/** Speed score out of 100, as a thin ring. */
function SpeedRing({ score }: { score: number }) {
  const r = 26;
  const c = 2 * Math.PI * r;
  return (
    <div className="relative size-[68px] shrink-0">
      <svg viewBox="0 0 64 64" className="size-full -rotate-90">
        <circle cx="32" cy="32" r={r} fill="none" stroke="var(--pv-line)" strokeWidth="5" />
        <circle
          cx="32"
          cy="32"
          r={r}
          fill="none"
          stroke="var(--pv-clear)"
          strokeWidth="5"
          strokeLinecap="round"
          strokeDasharray={c}
          strokeDashoffset={c * (1 - score / 100)}
          className="transition-[stroke-dashoffset] duration-700 ease-out"
        />
      </svg>
      <span className="absolute inset-0 flex items-center justify-center text-[18px] font-semibold tabular-nums tracking-[-0.02em] text-[var(--pv-ink)]">
        {score}
      </span>
    </div>
  );
}
